class DirtyVar<T : Any>(private val build: () -> T) {
    private var slot: T? = null

    operator fun getValue(ref: Any?, p: KProperty<*>): T =
        slot ?: build().also { slot = it }        // recompute when dirty

    operator fun setValue(ref: Any?, p: KProperty<*>, v: T?) { slot = null }
    fun invalidate() { slot = null }
}

